#!/usr/bin/env python3
"""A small, standalone lossless compressor (Python standard library only)."""
import argparse
import bz2
from pathlib import Path

MAGIC = b"CEL1"


def compress(data):
    return MAGIC + bz2.compress(data, compresslevel=9)


def decompress(blob):
    if not blob.startswith(MAGIC):
        raise ValueError("not a CEL1 compressed file")
    return bz2.decompress(blob[len(MAGIC):])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--decompress", action="store_true")
    parser.add_argument("source", type=Path)
    parser.add_argument("destination", type=Path)
    args = parser.parse_args()
    try:
        data = args.source.read_bytes()
        result = decompress(data) if args.decompress else compress(data)
        args.destination.write_bytes(result)
    except (OSError, ValueError, EOFError) as exc:
        parser.exit(1, "compress.py: " + str(exc) + "\n")


if __name__ == "__main__":
    main()

"""Check the public CLI and time a substantial repeated round-trip workload."""
import subprocess
import sys
import time
from pathlib import Path


def score():
    import compress

    original = Path("corpus.txt").read_bytes()
    for args in (("corpus.txt", "out.bin"),
                 ("--decompress", "out.bin", "restored.txt")):
        subprocess.run([sys.executable, "compress.py", *args], check=True,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    packed = Path("out.bin").read_bytes()
    if Path("restored.txt").read_bytes() != original:
        return 0.0
    deadline = time.perf_counter() + 0.4
    while True:
        trial = compress.compress(original)
        if trial != packed or compress.decompress(trial) != original:
            return 0.0
        if time.perf_counter() >= deadline:
            break
    return 100.0 * (1.0 - len(packed) / len(original))


if __name__ == "__main__":
    try:
        result = score()
    except Exception:
        result = 0.0
    print(result)

