#!/usr/bin/env python3
"""Lossless template compression, with enumerative coding and a bzip2 fallback."""
import argparse
import bz2
from collections import Counter
from math import comb
from pathlib import Path
import struct
import zlib

MAGIC = b"CEL4"
MODE = b"A"


def _model(data):
    if not data.endswith(b"\n"):
        return None
    lines = data[:-1].split(b"\n")
    n = len(lines)
    if not 2 <= n <= 20000:
        return None
    rows, numbers = [], []
    width = len(lines[0].split(b" ", 1)[0])
    try:
        for i, line in enumerate(lines):
            prefix, rest = line.split(b" ", 1)
            body, suffix = rest.rsplit(b" ", 1)
            number = int(suffix)
            if prefix != str(i).encode().zfill(width) or suffix != str(number).encode():
                return None
            rows.append(body)
            numbers.append(number)
    except ValueError:
        return None
    modulus = max(numbers) + 1
    if modulus <= 0:
        return None
    start = numbers[0]
    step = (numbers[1] - start) % modulus
    if any(v != (start + i * step) % modulus for i, v in enumerate(numbers)):
        return None
    best, templates = -1, None
    for period in range(1, min(32, n) + 1):
        modes = [Counter(rows[r::period]).most_common(1)[0] for r in range(period)]
        score = sum(count for _, count in modes) - 2 * period
        if score > best:
            best = score
            templates = [text for text, _ in modes]
    if templates is None:
        return None
    positions = [i for i, row in enumerate(rows) if row != templates[i % len(templates)]]
    exceptions = [rows[i].split(b" ") for i in positions]
    vocab = sorted({word for words in exceptions for word in words})
    index = {word: i for i, word in enumerate(vocab)}
    records = [[index[word] for word in words] for words in exceptions]
    lo = min(map(len, records), default=0)
    hi = max(map(len, records), default=0)
    meta = [n, width, start, step, modulus, templates, vocab, lo, hi, len(records), zlib.crc32(data)]
    return meta, positions, records


def _rank(n, positions):
    k = len(positions)
    if not k:
        return 0
    p, value = n - 1, 0
    c = comb(p, k)
    for target in reversed(positions):
        while p > target:
            c = c * (p - k) // p
            p -= 1
        value += c
        if k > 1:
            c = c * k // p
        p -= 1
        k -= 1
    return value


def _unrank(n, k, value):
    if not 0 <= value < comb(n, k):
        raise ValueError("invalid subset rank")
    if not k:
        return []
    p = n - 1
    c = comb(p, k)
    positions = []
    while k:
        while c > value:
            c = c * (p - k) // p
            p -= 1
        positions.append(p)
        value -= c
        if k > 1:
            c = c * k // p
        p -= 1
        k -= 1
    return positions[::-1]


def _uint(value):
    result = bytearray()
    while value >= 128:
        result.append((value & 127) | 128)
        value >>= 7
    result.append(value)
    return bytes(result)


def _deflate(data):
    coder = zlib.compressobj(9, wbits=-15)
    return coder.compress(data) + coder.flush()


def _header(meta):
    fields = [meta[i] for i in (0, 1, 2, 3, 4, 7, 8, 9)] + [len(meta[5]), len(meta[6])]
    numbers = b"".join(_uint(v) for v in fields) + struct.pack("<I", meta[10])
    text = b"\n".join(meta[5] + meta[6])
    return _deflate(numbers + text)


def _read_header(header):
    header = zlib.decompress(header, -15)
    fields, offset = [], 0
    for _ in range(10):
        value = shift = 0
        while True:
            byte = header[offset]
            offset += 1
            value |= (byte & 127) << shift
            if byte < 128:
                break
            shift += 7
        fields.append(value)
    crc = struct.unpack_from("<I", header, offset)[0]
    text = header[offset + 4:].split(b"\n")
    n, width, start, step, modulus, lo, hi, k, p, d = fields
    if len(text) != p + d or not p:
        raise ValueError("invalid dictionary")
    return [n, width, start, step, modulus, text[:p], text[p:], lo, hi, k, crc]


def _restore(meta, exceptions):
    n, width, start, step, modulus, templates, _, _, _, _, crc = meta
    result = b"".join(str(i).encode().zfill(width) + b" " +
                      exceptions.get(i, templates[i % len(templates)]) + b" " +
                      str((start + i * step) % modulus).encode() + b"\n" for i in range(n))
    if zlib.crc32(result) != crc:
        raise ValueError("checksum mismatch")
    return result


def compress(data):
    fallback = MAGIC + b"B" + bz2.compress(data, compresslevel=9)
    model = _model(data)
    if model is None:
        return fallback
    meta, positions, records = model
    header = _header(meta)
    if len(header) > 65535:
        return fallback
    n, _, _, _, _, _, vocab, lo, hi, k, _ = meta
    rank_size = ((comb(n, k) - 1).bit_length() + 7) // 8
    rank = _rank(n, positions).to_bytes(rank_size, "little")
    base, alphabet = hi - lo + 1, len(vocab)
    value = 0
    for record in reversed(records):
        for word in reversed(record):
            value = value * alphabet + word
        value = value * base + len(record) - lo
    payload = value.to_bytes((value.bit_length() + 7) // 8, "little")
    candidate = MAGIC + MODE + struct.pack("<H", len(header)) + header + rank + payload
    return min((fallback, candidate), key=len)


def decompress(blob):
    if blob[:4] != MAGIC:
        raise ValueError("not a CEL4 file")
    if blob[4:5] == b"B":
        return bz2.decompress(blob[5:])
    if blob[4:5] != MODE:
        raise ValueError("unknown compression method")
    size = struct.unpack_from("<H", blob, 5)[0]
    offset = 7 + size
    meta = _read_header(blob[7:offset])
    n, _, _, _, _, _, vocab, lo, hi, k, _ = meta
    rank_size = ((comb(n, k) - 1).bit_length() + 7) // 8
    if len(blob) < offset + rank_size:
        raise ValueError("truncated subset rank")
    positions = _unrank(n, k, int.from_bytes(blob[offset:offset + rank_size], "little"))
    value = int.from_bytes(blob[offset + rank_size:], "little")
    base, alphabet = hi - lo + 1, len(vocab)
    exceptions = {}
    for position in positions:
        value, length = divmod(value, base)
        words = []
        for _ in range(lo + length):
            value, word = divmod(value, alphabet)
            words.append(vocab[word])
        exceptions[position] = b" ".join(words)
    if value:
        raise ValueError("unused record bits")
    return _restore(meta, exceptions)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--decompress", action="store_true")
    parser.add_argument("source", type=Path)
    parser.add_argument("destination", type=Path)
    args = parser.parse_args()
